-- MANAGEMENT-PERSONAS-8 / DOER-ASSIGN-1 (2026-10-28, pillar autonomy). Owner directive 2026-10-28: audit and strengthen the portfolio, program and project
-- manager roles; the owner decides nothing and the system acts.
-- AUDIT (qnfo-audit, 2026-10-28 13Z): the managers decide and report (7 days: 84 lever-reviews, 62 closes, 26 demotes, 12 root-causes, 8 roadmap items originated,
-- 6 deployed), but a focus issue with no doer stays that way: program_focus holds 4 rows with has_doer = 0 (QNFO.RSCH 100464 since 2026-10-26, QNFO.REACH 100607 and
-- 2607, QNFO.OPS 2226). The managers name the gap in the brief and a lever (program_focus_without_doer) tells a reader to fix it; no manager step ever does. A gap with no
-- owner and no next action is itself a defect (core prompt rule 4).
-- WHAT: each hourly tick, for up to 4 focus issues (critical first) that have had no doer for 2 hours and no code-task line, the program manager asks the Cloudflare agent
-- (cf_agent_requests 'doer-<issue>-<day>') for one worker file and anchor; an answer in that form is checked like a roadmap proposal (control plane, .github, personal-* and
-- short anchors are rejected), written as the first lines of the issue so the code loop builds it (has_doer turns 1 on the next plan), and logged as persona_actions
-- doer-assign. A NO-CODE-FIX answer is logged as doer-gap with the reason, so the gap is a recorded finding, not silence; the same issue is not asked again for 3 days.
-- Prediction: program_focus_without_doer falls from 4 to <= 1 within 24 h unless the answers are NO-CODE-FIX; no guard metric worsens.
-- Stop: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('doer_assign', 'off');
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261028_mp8_workflow
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT definition FROM bak_20261028_mp8_workflow WHERE id = 'management-personas'), version = version + 1 WHERE id = 'management-personas'; INSERT OR REPLACE INTO ops_config (key, value) VALUES ('doer_assign', 'off');

CREATE TABLE IF NOT EXISTS bak_20261028_mp8_workflow AS SELECT id, definition, version FROM fleet_tasks WHERE id = 'management-personas';

CREATE TABLE IF NOT EXISTS doer_assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  issue_id INTEGER NOT NULL,
  instance TEXT UNIQUE,
  path TEXT,
  anchor_line TEXT,
  status TEXT NOT NULL DEFAULT 'proposed',
  outcome TEXT,
  created_at TEXT,
  updated_at TEXT
);

INSERT OR IGNORE INTO ops_config (key, value) VALUES ('doer_assign', 'on');

UPDATE fleet_tasks
SET definition = json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(json_insert(definition, '$.steps[#]', json('{"type":"sql","name":"dg-request","db":"AUDIT","sql":"INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:'' || f.program_code, ''run'', ''You are the program manager of '' || f.program_code || '' in the QNFO fleet (repository QNFO/qnfo-workers). Issue #'' || a.id || '' is in your focus and has no doer, so nothing will execute it: '' || a.title || char(10) || substr(COALESCE(a.description, ''''), 1, 1500) || char(10) || ''Read the code of the worker that owns it and name ONE worker file whose single change closes or measurably reduces it (never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator, qnfo-code-agent, .github or personal-*). Reply with exactly these two lines and nothing else:'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''If no single-file change can close it, reply with the one line NO-CODE-FIX: <reason, under 30 words>.'', ''doer-'' || f.issue_id || ''-'' || strftime(''%Y%m%d'', ''now''), ''high'' FROM program_focus f JOIN agent_issues a ON a.id = f.issue_id WHERE f.has_doer = 0 AND a.status = ''open'' AND f.program_code <> ''QNFO.PERSONAL'' AND f.entered_at <= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-2 hours'') AND COALESCE(a.description, '''') NOT LIKE ''%code-task:%'' AND NOT EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance LIKE ''doer-'' || f.issue_id || ''-%'' AND (r.status IN (''queued'', ''running'') OR (r.status = ''done'' AND COALESCE(r.result, '''') <> '''' AND r.created_at >= strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 days'')))) AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''doer_assign''), ''on'') <> ''off'' ORDER BY CASE a.priority WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 ELSE 2 END, f.entered_at LIMIT 4"}')), '$.steps[#]', json('{"type":"sql","name":"dg-parse","db":"AUDIT","sql":"INSERT OR IGNORE INTO doer_assignments (issue_id, instance, path, anchor_line, status, created_at, updated_at) WITH x AS (SELECT r.instance AS instance, replace(replace(r.result, ''**'', ''''), char(13), '''') AS s FROM cf_agent_requests r WHERE r.instance LIKE ''doer-%'' AND r.status = ''done''), y AS (SELECT instance, s, substr(s, instr(s, ''path='') + 5, 200) AS p, substr(s, instr(s, ''code-anchor:'') + 12) AS a FROM x WHERE instr(s, ''code-task: repo=qnfo-workers path='') > 0 AND instr(s, ''code-anchor:'') > 0) SELECT CAST(substr(instance, 6, length(instance) - 14) AS INTEGER), instance, trim(substr(p, 1, min(instr(p || char(10), char(10)), instr(p || '' '', '' '')) - 1), '' `*''), ''code-anchor: '' || trim(substr(a, 1, instr(a || char(10), char(10)) - 1), '' `*''), ''proposed'', strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') FROM y"}')), '$.steps[#]', json('{"type":"sql","name":"dg-nofix","db":"AUDIT","sql":"INSERT OR IGNORE INTO doer_assignments (issue_id, instance, status, outcome, created_at, updated_at) SELECT CAST(substr(r.instance, 6, length(r.instance) - 14) AS INTEGER), r.instance, ''no-code-fix'', substr(replace(replace(r.result, ''**'', ''''), char(13), ''''), instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''NO-CODE-FIX:''), 200), strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now''), strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') FROM cf_agent_requests r WHERE r.instance LIKE ''doer-%'' AND r.status = ''done'' AND instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''NO-CODE-FIX:'') > 0 AND instr(replace(replace(r.result, ''**'', ''''), char(13), ''''), ''code-task: repo='') = 0"}')), '$.steps[#]', json('{"type":"sql","name":"dg-reject","db":"AUDIT","sql":"UPDATE doer_assignments SET status = ''rejected'', outcome = ''not a single worker file the code loop may change: '' || COALESCE(path, ''(none)''), updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE status = ''proposed'' AND (path IS NULL OR path NOT LIKE ''%/%.%'' OR instr(path, '' '') > 0 OR instr(path, ''..'') > 0 OR path LIKE ''.github/%'' OR EXISTS (SELECT 1 FROM json_each(''[\"qnfo-fleet-control/\",\"qnfo-ops/\",\"qnfo-deploy-guard/\",\"qnfo-containers-pilot/\",\"qnfo-autonomy-scorer/\",\"qnfo-observability/\",\"qnfo-code-orchestrator/\",\"qnfo-code-agent/\",\"personal-\"]'') d WHERE instr(doer_assignments.path, d.value) = 1) OR length(anchor_line) < 33)"}')), '$.steps[#]', json('{"type":"sql","name":"dg-apply","db":"AUDIT","sql":"UPDATE agent_issues SET description = ''code-task: repo=qnfo-workers path='' || (SELECT d.path FROM doer_assignments d WHERE d.issue_id = agent_issues.id AND d.status = ''proposed'' ORDER BY d.id DESC LIMIT 1) || char(10) || (SELECT d.anchor_line FROM doer_assignments d WHERE d.issue_id = agent_issues.id AND d.status = ''proposed'' ORDER BY d.id DESC LIMIT 1) || char(10) || char(10) || ''Doer assigned by the program manager (DOER-ASSIGN-1): the issue was in focus with no doer, so the Cloudflare agent named the file above; the code loop builds it and the managers close the issue on verified evidence.'' || char(10) || char(10) || COALESCE(description, ''''), updated_at = CAST(strftime(''%s'', ''now'') AS INTEGER) * 1000 WHERE status = ''open'' AND COALESCE(description, '''') NOT LIKE ''%code-task:%'' AND EXISTS (SELECT 1 FROM doer_assignments d WHERE d.issue_id = agent_issues.id AND d.status = ''proposed'')"}')), '$.steps[#]', json('{"type":"sql","name":"dg-mark","db":"AUDIT","sql":"UPDATE doer_assignments SET status = ''assigned'', updated_at = strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'') WHERE status = ''proposed'' AND EXISTS (SELECT 1 FROM agent_issues a WHERE a.id = doer_assignments.issue_id AND instr(COALESCE(a.description, ''''), ''code-task: repo=qnfo-workers path='' || doer_assignments.path) = 1)"}')), '$.steps[#]', json('{"type":"sql","name":"dg-log","db":"AUDIT","sql":"INSERT INTO persona_actions (persona_key, kind, issue_id, from_value, to_value, evidence) SELECT ''program-manager:'' || COALESCE((SELECT f.program_code FROM program_focus f WHERE f.issue_id = d.issue_id LIMIT 1), ''QNFO.OPS''), CASE d.status WHEN ''assigned'' THEN ''doer-assign'' ELSE ''doer-gap'' END, d.issue_id, ''no doer'', d.status, CASE d.status WHEN ''assigned'' THEN ''code-task '' || d.path || '' written into the issue from Cloudflare agent research ('' || d.instance || '')'' ELSE ''no single-file fix ('' || d.instance || ''): '' || COALESCE(d.outcome, d.status) END FROM doer_assignments d WHERE d.status IN (''assigned'', ''no-code-fix'') AND NOT EXISTS (SELECT 1 FROM persona_actions a WHERE a.kind IN (''doer-assign'', ''doer-gap'') AND a.issue_id = d.issue_id AND a.to_value = d.status)"}')), '$.steps[#]', json('{"type":"sql","name":"dg-brief","db":"AUDIT","sql":"UPDATE persona_briefs SET summary = summary || '' Doer gaps: '' || (SELECT COUNT(*) FROM program_focus WHERE has_doer = 0) || '' open, '' || (SELECT COUNT(*) FROM doer_assignments WHERE status = ''assigned'') || '' assigned by the managers, '' || (SELECT COUNT(*) FROM doer_assignments WHERE status = ''no-code-fix'') || '' with no single-file fix.'' WHERE persona_key = ''portfolio-manager'' AND tick = (SELECT MAX(tick) FROM portfolio_allocations) AND summary NOT LIKE ''%Doer gaps:%''"}')),
  version = version + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE id = 'management-personas' AND instr(definition, '"dg-request"') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, surfaces_tested)
VALUES ('management-personas (MANAGEMENT-PERSONAS-8)', 'the owner decides nothing; a manager that reports a doer gap must close it itself',
  'hourly doer assignment for focus issues with no doer: Cloudflare agent research, validated code-task line written into the issue, persona_actions doer-assign / doer-gap',
  'program_focus held 4 has_doer = 0 rows on 2026-10-28, the oldest since 2026-10-26; no manager step assigned a doer', 'pending',
  'up to 4 cf_agent_requests a tick and the description of those issues; no worker code changes except through the code loop and the canonical deploy',
  'ops_config doer_assign = off; or the Rollback line of migrations/2026-10-28-management-personas-8.sql',
  'managers-assign-doers', 'program_focus_without_doer <= 1 within 24 h', 'cf_agent_requests, program_focus, code loop intake');
